/* @autogenerated */
package net.civeira.phylax.feature.observe.access;

import java.util.EnumSet;
import java.util.Set;

/**
 * Who calls the viewer api and with which levels.
 *
 * @param user name shown in the viewer
 * @param levels levels granted; {@link ObserveLevel#includes} applies
 */
public record ObserveGrant(String user, Set<ObserveLevel> levels) {

  public static ObserveGrant of(final String user, final ObserveLevel level) {
    return new ObserveGrant(user, EnumSet.of(level));
  }

  public boolean has(final ObserveLevel required) {
    return levels.stream().anyMatch(level -> level.includes(required));
  }

  /** The levels with the implied ones, as the viewer shows them. */
  public Set<ObserveLevel> effective() {
    Set<ObserveLevel> result = EnumSet.noneOf(ObserveLevel.class);
    for (ObserveLevel level : ObserveLevel.values()) {
      if (has(level)) {
        result.add(level);
      }
    }
    return result;
  }
}
